SELECT COUNT(*) AS so_benh_nhan_tu_vong
FROM patients
WHERE dod IS NOT NULL;

SELECT ROUND(AVG(so_chan_doan), 2) AS trung_binh_chan_doan_moi_dot
FROM (
  SELECT hadm_id, COUNT(*) AS so_chan_doan
  FROM diagnoses_icd
  GROUP BY hadm_id
) AS sub;

SELECT DISTINCT hadm_id, subject_id, drug, dose_val_rx, dose_unit_rx, route
FROM prescriptions
WHERE drug ILIKE '%Heparin%';

SELECT COUNT(DISTINCT subject_id) AS so_benh_nhan_tiem_iv
FROM prescriptions
WHERE route = 'IV';

SELECT ROUND(AVG(so_thu_thuat)::NUMERIC, 2) AS tb_thu_thuat_moi_dot
FROM (
  SELECT hadm_id, COUNT(*) AS so_thu_thuat
  FROM procedures_icd
  GROUP BY hadm_id
) AS sub;

SELECT ROUND(AVG(EXTRACT(EPOCH FROM (dischtime - admittime))/86400)::NUMERIC, 1) AS los_trung_binh_ngay
FROM admissions
WHERE dischtime IS NOT NULL AND admittime IS NOT NULL;
